class Solution {
    private int gcd(int a,int b){
        while(b!=0){
            int remainder=a%b;
            a=b;
            b=remainder;
        }
        return a;
    }
    public List<String> simplifiedFractions(int n){
        List<String> answer=new ArrayList<>();
        for(int denominator=2;denominator<=n;denominator++)for(int numerator=1;numerator<denominator;numerator++)if(gcd(numerator,denominator)==1)answer.add(numerator+"/"+denominator);
        return answer;
    }
}

code.kotlin:
class Solution {
    private fun gcd(a:Int,b:Int):Int=if(b==0)a else gcd(b,a%b);
    fun simplifiedFractions(n:Int):List<String>{
        val answer=mutableListOf<String>();
        for(denominator in 2..n)for(numerator in 1 until denominator)if(gcd(numerator,denominator)==1)answer.add("$numerator/$denominator");
        return answer
    }
}

